def join_media_url(base, rel):
    """Join a media base URL and relative path with exactly one slash.

    content_url often ends with '/' and stored paths often start with '/'.
    http-server does not collapse the extra slashes, so playback and covers 404.
    """
    base = "" if base is None else str(base)
    rel = "" if rel is None else str(rel)
    if not base:
        return rel.lstrip("/")
    if not rel:
        return base if base.endswith("/") else base + "/"
    return base.rstrip("/") + "/" + rel.lstrip("/")


def media_url_sql(base_expr, rel_expr):
    """SQL equivalent of join_media_url for content_directory URL columns."""
    return f"rtrim({base_expr}, '/') || '/' || ltrim({rel_expr}, '/')"

